def allocate(amount, weights):
    if type(amount) is not int or amount < 0:
        raise ValueError("amount must be a non-negative integer")
    if not isinstance(weights, (list, tuple)) or len(weights) == 0:
        raise ValueError("weights must be a non-empty list or tuple")
    for w in weights:
        if type(w) is not int or w < 0:
            raise ValueError("weights elements must be non-negative integers")
    total = sum(weights)
    if total == 0:
        raise ValueError("sum of weights must be positive")
    n = len(weights)
    if amount == 0:
        return [0] * n
    base = [amount * w // total for w in weights]
    remainders = [amount * w % total for w in weights]
    remaining = amount - sum(base)
    order = sorted(range(n), key=lambda i: (-remainders[i], i))
    result = base[:]
    for i in order[:remaining]:
        result[i] += 1
    return result
```

